import{_ as t,o as l,c as o,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Rook Deployed Scalable NFS Clusters Exporting CephFS - Patrick Donnelly & Jeff Layton, Red Hat, Inc.","description":"","frontmatter":{"title":"Rook Deployed Scalable NFS Clusters Exporting CephFS - Patrick Donnelly & Jeff Layton, Red Hat, Inc.","date":"2019-05-24T00:00:00.000Z","updated":"2019-05-24T00:00:00.000Z","tags":["Ceph","Distributed Storage","Rook","Kubernetes","NFS"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/Rook_Deployed_Scalable_NFS_Clusters_Exporting_CephFS_-_Patrick_Donnelly_Jeff_Layton_Red_Hat_Inc..md","filePath":"posts/2019/Rook_Deployed_Scalable_NFS_Clusters_Exporting_CephFS_-_Patrick_Donnelly_Jeff_Layton_Red_Hat_Inc..md","lastUpdated":1780459816000}'),a={name:"posts/2019/Rook_Deployed_Scalable_NFS_Clusters_Exporting_CephFS_-_Patrick_Donnelly_Jeff_Layton_Red_Hat_Inc..md"};function s(i,e,r,_,p,S){return l(),o("div",null,[...e[0]||(e[0]=[n('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2023年11月（具体日期未知）</p><p><strong>参会人员</strong>： Patrick Donnelly（Red Hat SEPA fest 技术负责人）、Jeff Lee（Red Hat 存储专家）</p><p><strong>会议主题</strong>： 深入探讨使用 Rook 在 Kubernetes 上部署可扩展的 NFS 集群，并导出 CephFS，介绍 SEPA fest 技术及其与 Ceph 的集成。</p><p><strong>会议内容</strong>：</p><p><strong>1. SEPA fest 简介</strong></p><ul><li>SEPA fest 是基于对象存储的 POSIX 分布式文件系统。</li><li>特点：MDS 集群化，元数据存储分离，客户端直接访问数据，无需与 MDS 交互，客户端和 MDS 共同维护元数据分布式缓存，确保数据一致性。</li><li>主要客户端：step views 和内核客户端。</li></ul><p><strong>2. 使用 Rook 部署 NFS 集群</strong></p><ul><li>部署原因：部分客户端可能无法直接处理 Ceph，需要通过网关进行转换，网络安全，例如防火墙保护集群数据，OpenStack Manila 等场景需要隔离数据访问。</li><li>目标：实现主动/主动部署，线性扩展集群，容器化部署，避免使用第三方软件，使用 NFS Ganesha 作为 NFS 服务器。</li></ul><p><strong>3. Ceph 集群与 NFS 网关</strong></p><ul><li>Ceph 集群支持主动/被动网关，但性能扩展性较差。</li><li>希望实现主动/主动部署，实现线性扩展。</li></ul><p><strong>4. NFS 协议</strong></p><ul><li>NFS 协议历史悠久，早期版本无状态，需要附加协议处理。</li><li>NFSv4 和 NFSv4.1 引入会话层和会话恢复机制。</li><li>Ganesha 使用 Ratius 存储跟踪客户端状态，支持会话恢复。</li></ul><p><strong>5. 复杂性挑战</strong></p><ul><li>网络文件系统（NFS）和集群文件系统（SEPA fest）都使用基于租约的会话机制，需要处理会话超时和租约过期等问题。</li><li>需要处理 IP 迁移，当 NFS Ganesha 服务器失败时，需要将 IP 地址迁移到新的服务器。</li></ul><p><strong>6. 解决方案</strong></p><ul><li>使用 Rook 和 Kubernetes 进行部署和管理。</li><li>利用 Kubernetes 的 IP 迁移功能。</li><li>通过 Rook 部署和管理 Ganesha 容器。</li><li>使用 Dashboard API 配置 Ganesha 导出。</li></ul><p><strong>7. 未来工作</strong></p><ul><li>支持基于子卷的主动/主动部署。</li><li>支持迁移到新的 IP 地址。</li><li>优化子卷的 grace 期。</li><li>与 SMB 集成。</li></ul><p><strong>行动计划</strong>：</p><ul><li>完善 Rook 和 Kubernetes 的集成。</li><li>优化 Ganesha 的配置和管理。</li><li>在 Ceph 中实现基于子卷的主动/主动部署。</li><li>研究与 SMB 的集成方案。</li></ul><p><strong>总结</strong>：</p><p>本次会议讨论了使用 Rook 和 Kubernetes 在 Ceph 上部署可扩展的 NFS 集群，并导出 CephFS 的方案。会议分析了相关技术和挑战，明确了未来工作方向和行动计划，为 Ceph 的存储功能扩展提供了新的思路。</p>',23)])])}const g=t(a,[["render",s]]);export{c as __pageData,g as default};
